using System.ComponentModel;
using System.Reflection;
namespace LadderRecords;
static class RecordsSettingsChecks
{
 // 창의 크기와 칸 너비는 창의 크기 단계만큼 큰 값으로 넣고 본다(100% 에서는 1120×650, 240). 너비를 기억하는 칸은 아티스트로 본다(곡명 칸은 남는 폭을 쓰므로 기억하지 않는다).
 // 정렬은 '최고 기록'(전의 '최고 점수 (%)')으로, 판정 필터는 지금의 이름('하드·맥스판정')으로 본다. 예전 판이 적어 둔 이름으로 여는 것은 맨 아래에서 따로 본다. 저장은 100% 때의 값으로 하므로 정수배가 아닌 단계에서는 1px 까지 다를 수 있다
 public static void Run(Catalog catalog){void Check(bool value,string name){if(!value)throw new Exception(name);}var root=Path.Combine(AppContext.BaseDirectory,"test-data",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var settings=Path.Combine(root,"view.json");var store=new RecordStore(Path.Combine(root,"records.json"));var song=catalog.Songs.Single(s=>s.Name=="Fundamental");foreach(var judge in new[]{"노말","하드","맥스"})store.SetManual(new(song.Id,8,"SC",judge,0),judge=="노말"?99m:judge=="하드"?97m:98m,1);T Field<T>(RecordsDialog dialog,string name)=>(T)typeof(RecordsDialog).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog)!;
  using(var dialog=new RecordsDialog(catalog,store,settings)){dialog.Show();Application.DoEvents();Field<ComboBox>(dialog,"judge").SelectedItem="하드·맥스판정";var grid=Field<RecordsView>(dialog,"grid");Check(grid.RowCount==2&&Enumerable.Range(0,2).All(i=>grid.ItemAt(i)!.Judge is "하드" or "맥스"),"Hard+max filter excludes normal and keeps both");Field<InputBox>(dialog,"search").Box.Text="Fundamental";Field<ComboBox>(dialog,"button").SelectedItem="8B";Field<ComboBox>(dialog,"pattern").SelectedItem="SC";grid.Sort("Best",ListSortDirection.Ascending);grid.Columns["Artist"]!.Width=Theme.S(240);dialog.Size=new(Theme.S(1120),Theme.S(650));dialog.Close();}
  using(var restored=new RecordsDialog(catalog,store,settings)){restored.Show();Application.DoEvents();var grid=Field<RecordsView>(restored,"grid");Check(Field<InputBox>(restored,"search").Box.Text=="Fundamental"&&Field<ComboBox>(restored,"button").Text=="8B"&&Field<ComboBox>(restored,"pattern").Text=="SC"&&Field<ComboBox>(restored,"judge").Text=="하드·맥스판정","Filters restored after new dialog construction");Check(grid.RowCount==2&&grid.ItemAt(0)!.Judge=="하드"&&grid.SortedColumn?.Name=="Best"&&grid.SortOrder==SortOrder.Ascending,"Saved numeric sort restored");Check(Math.Abs(grid.Columns["Artist"]!.Width-Theme.S(240))<=1&&Math.Abs(restored.Width-Theme.S(1120))<=1&&Math.Abs(restored.Height-Theme.S(650))<=1,$"Window and column sizes restored ({grid.Columns["Artist"]!.Width} {restored.Width}x{restored.Height})");Field<ComboBox>(restored,"judge").SelectedItem="전체";Check(grid.RowCount==3,"All judges still available");restored.Close();}
  // 히스토리의 그래프: 접힘과 PB 기준선은 바꾸는 즉시 목록의 설정 파일에 적히고, 다음에 열 때 이어진다
  using(var first=new RecordsDialog(catalog,store,settings)){first.Show();Application.DoEvents();first.OpenHistory();var history=first.History!;Check(history.Fold.Expanded&&history.PbLineBox.Checked&&history.Graph.Visible,"The graph starts unfolded with the PB line on");history.Fold.Flip();history.PbLineBox.Checked=false;Check(RecordsViewSettings.Load(settings) is {GraphFolded:true,PbLine:false,Search:"Fundamental",SortColumn:"Best"},"Folding and the PB line are written as they change, with the list's own settings");first.Close();}
  using(var again=new RecordsDialog(catalog,store,settings)){again.Show();Application.DoEvents();again.OpenHistory();var history=again.History!;Check(!history.Fold.Expanded&&!history.PbLineBox.Checked&&!history.Graph.Visible&&!history.Graph.PbLine,"The next history opens folded with the PB line off");again.Close();}
  // 예전 판이 적어 둔 설정(판정 '하드·맥스', 없어진 정렬 칸 '플레이 카운트'): 지금의 이름으로 옮겨 연다
  File.WriteAllText(settings,"{\"Judge\":\"하드·맥스\",\"SortColumn\":\"PlayCount\",\"Descending\":false,\"ColumnWidths\":{\"Song\":900,\"PlayCount\":300}}");
  using(var old=new RecordsDialog(catalog,store,settings)){old.Show();Application.DoEvents();var grid=Field<RecordsView>(old,"grid");Check(Field<ComboBox>(old,"judge").Text=="하드·맥스판정"&&grid.RowCount==2&&grid.SortedColumn?.Name=="LastPlayedAt"&&grid.SortOrder==SortOrder.Descending&&grid.Columns.Cast<ColumnHeader>().Sum(c=>c.Width)==grid.ClientSize.Width&&RecordsViewSettings.Load(settings) is {GraphFolded:false,PbLine:true},"Settings written by the older version open with the present names; the graph is unfolded with the PB line on");old.Close();}
  File.WriteAllText(settings,"invalid json");Check(RecordsViewSettings.Load(settings).Judge=="전체","Damaged settings fallback");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"records-settings-validation.txt"),"PASS: hard+max filter; normal exclusion; all judge option; search/button/pattern/judge persistence; numeric sort direction; window and column size; damaged settings fallback.");
 }
}
